H(s,'h1','OSI MODEL LAYERS','او ایس آئی ماڈل کی تہیں','د OSI ماډل طبقې')
add(s,'a','The OSI model defines a networking framework for implementing protocols in seven different layers. Control is passed from one layer to the next, starting at the application layer in one station, and proceeding to the bottom layer, over the channel to the next station and back up the hierarchy.','او ایس آئی ماڈل سات مختلف تہوں میں پروٹوکولز نافذ کرنے کے لیے نیٹ ورکنگ کا ڈھانچہ متعین کرتا ہے۔ کنٹرول ایک تہہ سے اگلی تہہ کو منتقل ہوتا ہے، ایک اسٹیشن میں ایپلیکیشن لیئر سے شروع ہو کر نچلی تہہ تک، پھر چینل کے ذریعے اگلے اسٹیشن تک اور درجہ بندی میں واپس اوپر تک۔','د OSI ماډل په اوو مختلفو طبقو کې د پروتوکولونو د پلي کولو لپاره د شبکې چوکاټ ټاکي. کنټرول له یوې طبقې نه بلې ته لېږدول کېږي، په یوه ایستګاه کې له اپلېکېشن طبقې پیلېږي، لاندېنۍ طبقې ته ځي، د چینل له لارې بلې ایستګاه ته او په درجه بندۍ کې بېرته پورته ځي.')
add(s,'b','The OSI model divides communications into seven different layers, where each include multiple hardware standards, protocols, or, other types of services. The OSI model has following seven layers.','او ایس آئی ماڈل مواصلات کو سات مختلف تہوں میں تقسیم کرتا ہے، جن میں سے ہر ایک میں متعدد ہارڈ ویئر معیارات، پروٹوکولز یا دیگر قسم کی خدمات شامل ہیں۔ او ایس آئی ماڈل کی درج ذیل سات تہیں ہیں۔','د OSI ماډل اړیکې په اوو مختلفو طبقو وېشي، چې هره یوه څو هارډویر معیارونه، پروتوکولونه یا نور ډول خدمتونه لري. د OSI ماډل لاندې اوه طبقې لري.')
L(s,[('l1','Physical Layer','فزیکل لیئر','فزیکي طبقه'),('l2','Data Link Layer','ڈیٹا لنک لیئر','د ډېټا نښلونې طبقه'),('l3','Network Layer','نیٹ ورک لیئر','د شبکې طبقه'),('l4','Transport Layer','ٹرانسپورٹ لیئر','د لېږد طبقه'),('l5','Session Layer','سیشن لیئر','د ناستې طبقه'),('l6','Presentation Layer','پریزنٹیشن لیئر','د وړاندې کولو طبقه'),('l7','Application Layer','ایپلیکیشن لیئر','د اپلېکېشن طبقه')],'osi_l')
def osi():
    names=['Application','Presentation','Session','Transport','Network','Data Link','Physical']
    cols=['#8b2e2e','#8fc7c9','#8fa8d6','#8ec99b','#d33','#e8a43a','#e86a3a']
    b=T(190,22,'OSI 7 Layer',16,'middle',700)
    for k,(n,cl) in enumerate(zip(names,cols)):
        y=45+k*32
        b+=f'<polygon points="20,{y+10} 140,{y} 160,{y+14} 40,{y+26}" fill="{cl}" stroke="#111"/>'+T(90,y+18,n,10,'middle',700,'#fff')
        b+=f'<polygon points="230,{y+10} 350,{y} 370,{y+14} 250,{y+26}" fill="{cl}" stroke="#111"/>'+T(300,y+18,n,10,'middle',700,'#fff')
    b+=T(60,40,'Transmit Data',9,'start',700)+T(255,40,'Receive Data',9,'start',700)
    b+='<line x1="170" y1="260" x2="220" y2="260" stroke="#111" stroke-width="3"/>'+T(195,277,'Physical Link',10,'middle',700)
    return svg(390,290,'OSI seven layers: application, presentation, session, transport, network, data link and physical, shown for transmitting and receiving stations',b)
s['figures']=[dict(svg=osi(),id='cs11-s162-fig1',caption='Figure 5.27 OSI Model Layers',captionUrdu='شکل ۵.۲۷ او ایس آئی ماڈل کی تہیں',captionPashto='انځور ۵.۲۷ د OSI ماډل طبقې',labels=[lab('Transmit Data','ڈیٹا بھیجیں','ډېټا ولېږئ'),lab('Receive Data','ڈیٹا وصول کریں','ډېټا ترلاسه کړئ'),lab('Physical Link','طبعی ربط','فزیکي تړاو')])]
F.fg(0)
